import java.util.*;

public class Solution {
    interface EvictionListener<K, V> {
        void onEvict(K chave, V valor);
    }

    record Stats(long hits, long misses, long evictions) {}

    // get/put/remove: O(1) de tempo. Espaço: O(capacidade).
    static class LruCache<K, V> {
        private final class No {
            K chave;
            V valor;
            No ant, prox;

            No(K chave, V valor) {
                this.chave = chave;
                this.valor = valor;
            }
        }

        private final int capacidade;
        private final EvictionListener<K, V> listener;
        private final Map<K, No> indice = new HashMap<>();
        // Sentinelas: cabeca.prox é o mais recente, cauda.ant é o menos recente.
        private final No cabeca = new No(null, null);
        private final No cauda = new No(null, null);
        private long hits, misses, evictions;

        LruCache(int capacidade, EvictionListener<K, V> listener) {
            if (capacidade < 1) throw new IllegalArgumentException("capacidade deve ser >= 1");
            this.capacidade = capacidade;
            this.listener = listener == null ? (k, v) -> {} : listener;
            cabeca.prox = cauda;
            cauda.ant = cabeca;
        }

        Optional<V> get(K chave) {
            No no = indice.get(chave);
            if (no == null) {
                misses++;
                return Optional.empty();
            }
            hits++;
            desligar(no);
            inserirNaFrente(no);
            return Optional.of(no.valor);
        }

        void put(K chave, V valor) {
            if (chave == null || valor == null) throw new IllegalArgumentException("chave e valor obrigatorios");
            No no = indice.get(chave);
            if (no != null) {
                no.valor = valor;
                desligar(no);
                inserirNaFrente(no);
                return;
            }
            no = new No(chave, valor);
            indice.put(chave, no);
            inserirNaFrente(no);
            if (indice.size() > capacidade) {
                No lru = cauda.ant;
                desligar(lru);
                indice.remove(lru.chave);
                evictions++;
                // Estado já consistente: uma exceção do listener não corrompe o cache.
                listener.onEvict(lru.chave, lru.valor);
            }
        }

        Optional<V> remove(K chave) {
            No no = indice.remove(chave);
            if (no == null) return Optional.empty();
            desligar(no);
            return Optional.of(no.valor);
        }

        int size() {
            return indice.size();
        }

        List<K> keysMostRecentFirst() {
            List<K> chaves = new ArrayList<>(indice.size());
            for (No n = cabeca.prox; n != cauda; n = n.prox) chaves.add(n.chave);
            return chaves;
        }

        Stats stats() {
            return new Stats(hits, misses, evictions);
        }

        private void desligar(No no) {
            no.ant.prox = no.prox;
            no.prox.ant = no.ant;
        }

        private void inserirNaFrente(No no) {
            no.prox = cabeca.prox;
            no.ant = cabeca;
            cabeca.prox.ant = no;
            cabeca.prox = no;
        }
    }
}

