import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.time.Duration;
import java.util.*;

class SolutionTest {
    final List<String> despejados = new ArrayList<>();

    Solution.LruCache<String, Integer> cache(int cap) {
        return new Solution.LruCache<>(cap, (k, v) -> despejados.add(k + "=" + v));
    }

    @Test void despejaOMenosRecente() {
        var c = cache(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        assertEquals(List.of("b=2"), despejados);
        assertEquals(List.of("c", "a"), c.keysMostRecentFirst());
        assertEquals(Optional.empty(), c.get("b"));
    }

    @Test void atualizarNaoDespejaEPromove() {
        var c = cache(2);
        c.put("a", 1);
        c.put("b", 2);
        c.put("a", 9);
        assertTrue(despejados.isEmpty());
        assertEquals(List.of("a", "b"), c.keysMostRecentFirst());
        assertEquals(Optional.of(9), c.get("a"));
        c.put("c", 3);
        assertEquals(List.of("b=2"), despejados);
    }

    @Test void removeNaoEhEviction() {
        var c = cache(2);
        c.put("a", 1);
        assertEquals(Optional.of(1), c.remove("a"));
        assertEquals(Optional.empty(), c.remove("a"));
        assertTrue(despejados.isEmpty());
        assertEquals(0, c.size());
        assertEquals(new Solution.Stats(0, 0, 0), c.stats());
    }

    @Test void stats() {
        var c = cache(1);
        c.put("a", 1);
        c.get("a");
        c.get("x");
        c.put("b", 2);
        c.get("a");
        assertEquals(new Solution.Stats(1, 2, 1), c.stats());
    }

    @Test void capacidadeUm() {
        var c = cache(1);
        c.put("a", 1);
        c.put("b", 2);
        assertEquals(List.of("b"), c.keysMostRecentFirst());
        assertEquals(1, c.size());
    }

    @Test void listenerNuloEhPermitido() {
        var c = new Solution.LruCache<Integer, String>(1, null);
        c.put(1, "um");
        c.put(2, "dois");
        assertEquals(List.of(2), c.keysMostRecentFirst());
    }

    @Test void entradasInvalidas() {
        assertThrows(IllegalArgumentException.class, () -> cache(0));
        var c = cache(1);
        assertThrows(IllegalArgumentException.class, () -> c.put(null, 1));
        assertThrows(IllegalArgumentException.class, () -> c.put("a", null));
    }

    @Test void listenerQueFalhaNaoCorrompeOCache() {
        var c = new Solution.LruCache<String, Integer>(1, (k, v) -> { throw new IllegalStateException("disco cheio"); });
        c.put("a", 1);
        assertThrows(IllegalStateException.class, () -> c.put("b", 2));
        assertEquals(1, c.size());
        assertEquals(List.of("b"), c.keysMostRecentFirst());
        assertEquals(Optional.of(2), c.get("b"));
    }

    @Test void muitasOperacoesEmTempoConstante() {
        assertTimeout(Duration.ofSeconds(3), () -> {
            var c = new Solution.LruCache<Integer, Integer>(1_000, null);
            for (int i = 0; i < 200_000; i++) {
                c.put(i, i);
                c.get(i - 500);
            }
            assertEquals(1_000, c.size());
            assertEquals(199_000, c.stats().evictions());
            // o último get(i - 500) promoveu 199_499 para o topo
            assertEquals(199_499, c.keysMostRecentFirst().get(0));
            assertEquals(199_999, c.keysMostRecentFirst().get(1));
        });
    }
}
